const MAX_PER_SOURCE = 2800;
const sources = $input.first().json.all_sources;

// Extraction robuste qui gère DEUX formats différents :
// - Atom (The Verge) : balises <entry>, <title type="html">, <summary type="html">
// - RSS 2.0 (MIT, VentureBeat) : balises <item>, <title>, <description>
// La différence fondamentale : les attributs dans les balises Atom (type="html")
// empêchaient le pattern <title>...</title> de matcher

function extractTag(xml, tagName) {
  const results = [];
  // Pattern avec [^>]* pour capturer les attributs éventuels (type="html", etc.)
  const re = new RegExp('<' + tagName + '[^>]*>([\\s\\S]*?)<\\/' + tagName + '>', 'gi');
  let match;
  while ((match = re.exec(xml)) !== null) {
    let val = match[1];
    // Nettoyage CDATA si présent
    const cdataMatch = val.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
    if (cdataMatch) val = cdataMatch[1];
    // Suppression des balises HTML internes + décodage entités de base
    val = val
      .replace(/<[^>]+>/g, '')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#\d+;/g, '')
      .replace(/&[a-z]+;/g, '')
      .trim();
    if (val.length > 3) results.push(val);
  }
  return results;
}

function processSource(xml, sourceName) {
  // Détection du format : Atom utilise <entry>, RSS utilise <item>
  const isAtom = xml.indexOf('<entry>') !== -1 || xml.indexOf('<feed') !== -1;

  if (isAtom) {
    // Format Atom (The Verge) : les titres d'articles sont dans les <entry>
    // On extrait chaque bloc <entry> puis son <title> interne
    const entryRe = new RegExp('<entry>([\\s\\S]*?)<\\/entry>', 'gi');
    const articles = [];
    let entryMatch;
    while ((entryMatch = entryRe.exec(xml)) !== null && articles.length < 9) {
      const entryContent = entryMatch[1];
      // Titre de l'article dans le entry
      const titleRe = new RegExp('<title[^>]*>([\\s\\S]*?)<\\/title>', 'i');
      const titleMatch = entryContent.match(titleRe);
      // Résumé dans <summary>
      const summaryRe = new RegExp('<summary[^>]*>([\\s\\S]*?)<\\/summary>', 'i');
      const summaryMatch = entryContent.match(summaryRe);

      if (titleMatch) {
        let title = titleMatch[1];
        // Extraction CDATA si présent
        const cdata = title.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
        if (cdata) title = cdata[1];
        title = title.replace(/<[^>]+>/g, '').replace(/&#\d+;/g, '').replace(/&[a-z]+;/g, '').trim();

        let summary = '';
        if (summaryMatch) {
          summary = summaryMatch[1];
          const cdataS = summary.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
          if (cdataS) summary = cdataS[1];
          summary = summary.replace(/<[^>]+>/g, '').replace(/&#\d+;/g, '').replace(/&[a-z]+;/g, '').trim().substring(0, 180);
        }

        if (title.length > 10) {
          articles.push('* ' + title + (summary ? ' — ' + summary : ''));
        }
      }
    }
    return ('[SOURCE: ' + sourceName + ']\n' + articles.join('\n')).substring(0, MAX_PER_SOURCE);

  } else {
    // Format RSS 2.0 (MIT, VentureBeat) : les articles sont dans les <item>
    const itemRe = new RegExp('<item>([\\s\\S]*?)<\\/item>', 'gi');
    const articles = [];
    let itemMatch;
    while ((itemMatch = itemRe.exec(xml)) !== null && articles.length < 9) {
      const itemContent = itemMatch[1];
      const titleRe = new RegExp('<title[^>]*>([\\s\\S]*?)<\\/title>', 'i');
      const descRe = new RegExp('<description[^>]*>([\\s\\S]*?)<\\/description>', 'i');
      const titleMatch = itemContent.match(titleRe);
      const descMatch = itemContent.match(descRe);

      if (titleMatch) {
        let title = titleMatch[1];
        const cdata = title.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
        if (cdata) title = cdata[1];
        title = title.replace(/<[^>]+>/g, '').replace(/&#\d+;/g, '').replace(/&[a-z]+;/g, '').trim();

        let desc = '';
        if (descMatch) {
          desc = descMatch[1];
          const cdataD = desc.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
          if (cdataD) desc = cdataD[1];
          desc = desc.replace(/<[^>]+>/g, '').replace(/&#\d+;/g, '').replace(/&[a-z]+;/g, '').trim().substring(0, 180);
        }

        if (title.length > 10) {
          articles.push('* ' + title + (desc ? ' — ' + desc : ''));
        }
      }
    }
    return ('[SOURCE: ' + sourceName + ']\n' + articles.join('\n')).substring(0, MAX_PER_SOURCE);
  }
}

const extracted = sources.map(function(item, idx) {
  // Cas RSS/Atom
  if (item.data && typeof item.data === 'string') {
    const sourceNames = ['The Verge AI', 'MIT Technology Review', 'VentureBeat AI'];
    return processSource(item.data, sourceNames[idx] || ('RSS Source ' + (idx + 1)));
  }
  // Cas Perplexity
  if (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content) {
    return ('[SOURCE: Perplexity Sonar Pro - Recherche web 24h]\n' + item.choices[0].message.content).substring(0, MAX_PER_SOURCE);
  }
  return null;
}).filter(function(s) { return s !== null; });

const finalContext = extracted.join('\n\n====================\n\n');
return [{ json: { extracted_context: finalContext, source_count: extracted.length } }];
